package ie.suric.suricapp.local

/** Additional offline reference material for the seven subject libraries. */
internal object StarterLibraryExpansion {
    private const val REVIEWED = "18 October 2026"
    private fun block(heading: String, vararg lines: String) = StarterBlock(heading, lines.toList())

    private fun guide(
        id: String,
        category: String,
        title: String,
        summary: String,
        vararg blocks: StarterBlock,
        sources: List<Pair<String, String>> = emptyList(),
        related: List<String> = emptyList()
    ) = StarterItem(
        id = id,
        category = category,
        title = title,
        summary = summary,
        type = StarterType.GUIDE,
        blocks = blocks.toList(),
        imageKey = when (category) {
            "Gardening" -> "suric_garden"
            "Pottery" -> "suric_pottery"
            "Shopping" -> "suric_shopping"
            "DIY & Home" -> "suric_diy"
            "Cooking" -> "suric_cooking"
            "Cleaning" -> "suric_cleaning"
            "Retro & Android" -> "suric_retro"
            else -> null
        },
        reviewed = REVIEWED,
        sources = sources,
        destination = when (category) {
            "Gardening" -> "Garden"
            "DIY & Home" -> "DIY & Home"
            else -> category
        },
        relatedIds = related
    )

    private fun recipe(
        id: String,
        title: String,
        summary: String,
        yield: String,
        prep: String,
        cook: String,
        ingredients: List<String>,
        method: List<String>,
        tips: List<String>,
        storage: String,
        related: List<String> = emptyList()
    ) = StarterItem(
        id = id,
        category = "Cooking",
        title = title,
        summary = summary,
        type = StarterType.RECIPE,
        blocks = listOf(
            block("Yield and timing", "Serves: $yield", "Preparation: $prep", "Cooking: $cook"),
            block("Ingredients", *ingredients.toTypedArray()),
            block("Method", *method.toTypedArray()),
            block("Tips and variations", *tips.toTypedArray()),
            block("Storage", storage)
        ),
        imageKey = "suric_cooking",
        reviewed = REVIEWED,
        sources = listOf("Food Safety Authority of Ireland — cooking and reheating" to "https://www.fsai.ie/consumer-advice/food-safety-and-hygiene/cooking-and-reheating"),
        destination = "Cooking",
        relatedIds = related
    )

