        recipe("cook.croatian-sarma", "Croatian-style sarma", "Cabbage leaves wrapped around a seasoned meat-and-rice filling and simmered slowly with sauerkraut. Household versions vary by region and family.", "6", "45 minutes", "about 2 hours", listOf(
            "12–16 large pickled cabbage leaves, rinsed if very salty", "500 g minced pork", "250 g minced beef", "100 g uncooked short-grain rice, rinsed", "1 medium onion, finely chopped", "2 garlic cloves, crushed", "1 tsp sweet paprika", "½ tsp black pepper", "1 tbsp oil", "500 g sauerkraut", "700 ml stock or water", "1 bay leaf", "Optional to serve: bread or mashed potatoes"), listOf(
            "Mix pork, beef, rice, onion, garlic, paprika, pepper and 2 tbsp water. Do not overwork.", "Trim thick ribs from cabbage leaves. Place a portion of filling near the base, fold in the sides and roll snugly without compressing the filling too tightly.", "Spread half the sauerkraut in a heavy pot. Arrange rolls seam-side down, add remaining sauerkraut and bay leaf.", "Pour in stock until the rolls are nearly covered. Bring just to a gentle simmer, cover and cook slowly for about 1 hour 45 minutes, checking liquid level.", "Check a central roll: rice must be tender and the filling cooked through. If using a thermometer, check the centre reaches a safe temperature for minced meat; use current FSAI guidance.", "Rest briefly, remove bay leaf and serve with some cooking liquid."), listOf("If leaves are very salty, rinse and taste a small piece first.", "Keep rolls small and similar in size for even cooking.", "Avoid vigorous boiling, which can loosen the rolls."), "Cool promptly, refrigerate covered and use within 2 days. Reheat until steaming hot throughout. Keep raw meat separate from ready-to-eat food.", related = listOf("cook.paprika-pork-stew", "cook.bread-dumplings")),
        recipe("cook.paprika-pork-stew", "Paprika pork stew", "A simple Central European-style stew with sweet paprika, onions and tender pork; serve with bread or dumplings.", "4", "20 minutes", "1 hour 30 minutes", listOf(
            "700 g pork shoulder, cut into 3 cm pieces", "2 tbsp neutral oil", "2 large onions, finely chopped", "2 garlic cloves, chopped", "2 tbsp sweet paprika", "1 tbsp tomato purée", "500 ml stock or water", "1 red pepper, diced", "1 tsp caraway seeds, optional", "Salt and black pepper", "1 tbsp flour mixed with cold water, optional thickener"), listOf(
