        guide("clean.laundry-symbols-and-sorting", "Cleaning", "Sort laundry and read care labels", "The care label is the authority for the garment; sorting by colour and fabric reduces avoidable damage.",
            block("Sort", "Separate whites, dark colours and strongly coloured new items; wash a new item separately if its colour may run.", "Separate lint-producing fabrics from lint-attracting items and heavy soil from lightly worn clothes.", "Check pockets, close zips and turn delicate prints inside out where appropriate."),
            block("Read the label", "The wash tub gives the maximum wash temperature; a hand symbol means hand wash, and a crossed tub means do not wash in water.", "The triangle relates to bleach, the square to drying and the iron to ironing; dots indicate heat level.", "A crossed circle means do not dry-clean. If the label is unclear, choose the gentlest compatible care or ask the manufacturer.", "Use detergent amount and cycle according to the machine and detergent instructions; more detergent does not necessarily clean better."),
            sources = listOf("Ginetex — care symbols" to "https://www.ginetex.net/GB/labelling/care-symbols.asp"), related = listOf("clean.stain-first-response", "clean.appliance-monthly")),
        guide("clean.stain-first-response", "Cleaning", "Respond to a household stain", "Identify the fabric and stain before applying a cleaner. Heat, rubbing and incompatible chemicals can make damage permanent.",
            block("First response", "Check the item's care label and the cleaner label. Test any product on a hidden area first.", "Lift solids gently with a spoon or blunt edge; blot liquid from the outside toward the centre with a clean cloth.", "Avoid rubbing delicate fibres or spreading the stain. Do not apply heat until the stain has been treated and checked."),
            block("Choose a method", "Water-based spills often respond to cool water and a small amount of compatible detergent, but dyes and delicate fabrics need a hidden test.", "Oil, ink, protein and tannin stains need different approaches; do not assume one product is safe for all.", "Never mix bleach with acids, ammonia or another cleaner. Use one labelled product at a time and rinse as directed.", "For valuable, delicate, unknown or dry-clean-only materials, use a professional cleaner and tell them what was applied."),
            sources = listOf("HSE — safe use of cleaning chemicals" to "https://www.hse.gov.uk/pubns/cais22.pdf"), related = listOf("clean.laundry-symbols-and-sorting", "clean.surface-compatibility")),
        guide("clean.surface-compatibility", "Cleaning", "Choose a cleaner for the surface", "A product that works on one material can etch, dull or stain another. The surface and product instructions take priority.",
            block("Check the material", "Identify whether the surface is natural stone, sealed wood, laminate, stainless steel, glass, enamel or a coated finish.", "Read the surface manufacturer's care guidance before using acids, abrasives, solvents or bleach.", "Test a small inconspicuous area, use the recommended dilution and dwell time, and rinse or dry if instructed."),
            block("Avoid common damage", "Do not use acidic descalers on acid-sensitive stone or cement-based grout unless the maker explicitly permits it.", "Avoid abrasive pads and powders on glossy coatings, non-stick surfaces and polished finishes.", "Do not soak wood joints or leave standing water on floors; use a damp, well-wrung cloth where appropriate.", "Never mix cleaners. Keep products in original containers and ventilate as directed."),
            sources = listOf("HSE — safe use of cleaning chemicals" to "https://www.hse.gov.uk/pubns/cais22.pdf"), related = listOf("clean.stain-first-response", "clean.mould-and-moisture-awareness")),
        guide("clean.mould-and-moisture-awareness", "Cleaning", "Treat moisture as the cause of recurring mould", "Cleaning visible mould may remove marks, but persistent moisture must be addressed to prevent recurrence.",
            block("Reduce moisture", "Use extractor fans and openable windows as intended; keep vents unobstructed.", "Wipe condensation from cold windows and surfaces, and dry wet areas after use.", "Avoid drying large amounts of laundry in a poorly ventilated room when another option is available.", "Check for leaks, failed seals, blocked gutters or cold spots if mould returns in the same location."),
            block("Clean cautiously", "For a small patch on a suitable hard surface, follow public-health and product-label advice; wear the protection the product specifies.", "Do not dry-brush mould or mix cleaning products. Keep children and pets away during cleaning and until the area is dry.", "Porous materials, large areas, repeated growth or mould linked to a leak may need professional assessment.", "Seek medical advice for health concerns; this guide does not diagnose illness or building defects."),
            sources = listOf("Government of Ireland — home ventilation" to "https://www.gov.ie/en/department-of-housing-local-government-and-heritage/publications/home-ventilation/", "Citizens Information — minimum standards for rented homes" to "https://www.citizensinformation.ie/en/housing/renting-a-home/tenants-rights-and-responsibilities/minimum-standards-for-rented-homes/"), related = listOf("diy.plumbing-electrical-boundaries", "clean.surface-compatibility")),

        // Retro & Android — explanatory guides plus reviewed entry points to primary/community references.
        guide("retro.ps1-hardware-and-preservation", "Retro & Android", "PlayStation 1 hardware and preservation basics", "Model family, region, video output and disc condition affect repair and preservation choices; identify the console before buying parts.",
            block("Identify the console", "Record the SCPH model code from the underside label, region and any board markings visible during qualified repair.", "The PS1 family includes revisions with changes to board layout, drive assembly and video behaviour; parts are not universally interchangeable.", "Check the controller port, memory-card slots, optical drive, AV output and power supply before diagnosing a game problem."),
            block("Preserve and troubleshoot", "Use original discs you own or lawful personal archival copies where local law permits; this library does not provide game files.", "Clean a disc gently from the centre outward with a suitable soft cloth. Avoid solvents and aggressive polishing.", "If a game freezes, compare another known-good disc and inspect the disc surface before opening the console.", "For internal power-supply or board repair, use a qualified technician; mains voltage and charged components can be dangerous."),
            sources = listOf("ConsoleMods Wiki — PlayStation references" to consoleMods, "Sony PlayStation support" to "https://www.playstation.com/en-ie/support/hardware/"), related = listOf("retro.ps2-models-storage", "retro.ps1-video-and-repair")),
        guide("retro.ps1-video-and-repair", "Retro & Android", "PS1 video, accessories and common faults", "Start with reversible checks: cable, display input, controller, memory card and a known-good original disc.",
            block("Video path", "The original multi-out provides analogue video/audio; output quality and supported modes depend on the console revision, cable and display.", "Try a known-compatible cable and another display input before assuming the console has failed.", "Modern displays may add scaling delay or reject some legacy signals; a purpose-built scaler can help but must match the output standard."),
            block("Basic fault isolation", "No picture: check the TV input, cable seating and another known-good cable; inspect connector pins for damage.", "Disc not recognised: test a clean, known-good disc and listen for abnormal drive sounds without forcing the mechanism.", "Controller or save issue: test another controller and memory card, and verify the card is seated in the correct slot.", "Document model and symptoms before sourcing a replacement part; use a model-specific repair guide and avoid live internal work."),
            sources = listOf("ConsoleMods Wiki — PlayStation references" to consoleMods), related = listOf("retro.ps1-hardware-and-preservation")),
        guide("retro.ps2-models-storage", "Retro & Android", "PS2 Fat and Slim models, storage and compatibility", "PS2 revisions differ in network hardware, drive design and homebrew paths; the exact SCPH code is the starting point.",
            block("Identify", "Record the SCPH-xxxxx model code and region. Do not rely on the case colour or seller description.", "Fat models use an internal expansion bay on supported revisions; Slim models generally use different network and storage arrangements.", "Check whether the console includes a working network adapter, memory card, power supply and controller before purchasing accessories."),
            block("Plan storage", "Open PS2 Loader supports multiple device paths, but speed, compatibility and configuration differ between USB, network and internal-drive setups.", "USB 1.1 is a bandwidth limit on PS2; do not assume a USB storage setup will perform like a modern console.", "Use the current OPL user guide and compatibility notes for the exact version and device arrangement.", "Keep personal saves backed up to more than one medium; storage hardware can fail."),
            sources = listOf("Open PS2 Loader project" to "https://github.com/ps2homebrew/Open-PS2-Loader", "Open PS2 Loader User Guide" to "https://github.com/ps2homebrew/Open-PS2-Loader-User-Guide", "ConsoleMods Wiki — PS2" to "https://consolemods.org/wiki/PS2:Getting_started"), related = listOf("retro.ps2-homebrew-overview", "shopping.storage-basics")),
        guide("retro.ps2-homebrew-overview", "Retro & Android", "PS2 homebrew: understand the route before changing anything", "Homebrew is community-made software. Which launch path is suitable depends on model, accessories and current console state.",
            block("Choose by constraints", "Free McBoot is a memory-card-based environment used by many compatible PS2 setups; compatibility and installation method vary.", "Open PS2 Loader is a homebrew application for launching supported content from configured storage devices; consult its current compatibility list.", "Some approaches require a compatible disc, memory card, network adapter or a computer-assisted setup.", "Do not follow a guide written for another model or assume every Slim or Fat unit behaves identically."),
            block("Protect the console and data", "Record model, region, existing modifications and current working behaviour before changing files or hardware.", "Use the project repository or maintained guide as the source of truth; avoid download mirrors that bundle unknown files.", "Use homebrew for lawful applications, your own saves and preservation work. This guide does not provide commercial game images.", "Keep one known-working boot path and a copy of important save data before experimenting."),
            sources = listOf("PS2 Homebrew Projects" to "https://github.com/ps2homebrew", "Open PS2 Loader" to "https://github.com/ps2homebrew/Open-PS2-Loader", "ConsoleMods Wiki — PS2" to "https://consolemods.org/wiki/PS2:Getting_started"), related = listOf("retro.ps2-models-storage", "retro.homebrew-source-checking")),
        guide("retro.ps3-models-cfw-hen", "Retro & Android", "PS3: model checks, CFW and HEN are different paths", "PS3 compatibility is model and firmware dependent. Never choose a method from the family name alone.",
            block("Identify first", "Record the full CECH model code, current system software version, region and whether the console is CEX or a specialist development unit.", "Some early Fat and selected Slim models may be capable of custom firmware; later Slim and Super Slim models generally use a different homebrew route.", "Minimum-version and flash compatibility checks are model-specific. Use a current maintained model guide before any system modification."),
            block("Understand the terms", "CFW replaces or patches parts of the system software on compatible hardware; HEN is a homebrew enabler with a different install and activation model.", "HEN is not interchangeable with CFW, and tools or instructions for one path may not work on the other.", "Firmware support changes over time. The PS3HEN project's own release notes and a current model guide take precedence over this overview.", "Back up saves and important data first; incorrect firmware files, interrupted updates or unsupported hardware can make recovery difficult."),
            sources = listOf("PS3HEN official project" to "https://github.com/PS3Xploit/PS3HEN", "ConsoleMods Wiki — PS3 getting started" to "https://consolemods.org/wiki/PS3:Getting_Started", "Sony PS3 system software support" to "https://www.playstation.com/en-ie/support/hardware/ps3/system-software/"), related = listOf("retro.ps3-maintenance-recovery", "retro.homebrew-source-checking")),
        guide("retro.ps3-maintenance-recovery", "Retro & Android", "PS3 storage, heat and recovery checklist", "A structured symptom record helps distinguish a failing drive, overheating, power issue or software problem.",
            block("Before troubleshooting", "Record CECH model, firmware, recent changes, error code, lights/beeps and whether the fault occurs cold or after warming.", "Back up saves and irreplaceable data while the console still starts; do not begin by formatting the drive.", "Check ventilation clearance, dust at external vents, fan noise and whether the console is on a hard, open surface."),
            block("Safe checks", "Use Sony's official Safe Mode and storage instructions for ordinary system recovery; read the data-loss warning on each option.", "If replacing a drive, confirm the replacement type and prepare the correct official system software from Sony's support page.", "Do not repeatedly power-cycle a console with suspected drive, power-supply or board failure.", "For thermal paste, delidding, soldering or power-supply repair, use a qualified console technician; these are not routine maintenance steps."),
            sources = listOf("Sony PS3 system software support" to "https://www.playstation.com/en-ie/support/hardware/ps3/system-software/", "ConsoleMods Wiki — PS3 FAQ" to "https://consolemods.org/wiki/PS3:FAQ"), related = listOf("retro.ps3-models-cfw-hen", "diy.maintenance")),
        guide("retro.ps4-firmware-compatibility", "Retro & Android", "PS4 modification research starts with firmware", "PS4 homebrew compatibility is firmware-sensitive. There is no safe assumption that the newest firmware is supported.",
            block("Record before researching", "Read the complete system software version in Settings and record the CUH model code.", "Do not update merely to test an exploit or follow a tutorial. An official update can remove access to a previously supported environment.", "Check the current compatibility chart and project release notes on the same day you plan to act; online tables become stale.", "Treat a video as a walkthrough, not the compatibility authority. Confirm every prerequisite in maintained project documentation."),
            block("Plan for consequences", "Expect possible loss of online services, account features, save access or warranty support; review current platform terms and project warnings.", "Back up saves and important files using a method compatible with your current firmware before making changes.", "Verify the console is yours, understand recovery limitations and keep the official recovery procedure available.", "This offline article intentionally does not freeze a list of supported firmware versions."),
            sources = listOf("ConsoleMods Wiki — PS4 getting started and compatibility" to "https://consolemods.org/wiki/PS4:Getting_Started", "ConsoleMods Wiki — PS4 exploit chart" to "https://consolemods.org/wiki/PS4:Exploit_Chart", "MODDED WARFARE — channel" to "https://www.youtube.com/@moddedwarfare"), related = listOf("retro.ps4-backup-and-recovery", "retro.homebrew-source-checking")),
        guide("retro.ps4-backup-and-recovery", "Retro & Android", "PS4 backups, storage and recovery", "Use official backup and recovery information for ordinary maintenance; modification changes the available recovery path.",
            block("Routine care", "Back up saves and captures using an official supported option before replacing storage or changing system software.", "Use the exact internal drive specification and Sony's current reinstall instructions when replacing a drive.", "Keep the reinstall file and backup on separate storage; confirm the backup is readable before erasing the console."),
            block("If something fails", "Write down the Safe Mode code or screen message and what changed immediately before it appeared.", "Use official PlayStation recovery instructions first for an unmodified console.", "If the system has been modified, consult the exact project's recovery notes; a stock recovery update can remove the modification or worsen a mismatched setup.", "Avoid random firmware files and recovery packages from reupload sites."),
            sources = listOf("PlayStation 4 support" to "https://www.playstation.com/en-ie/support/hardware/ps4/", "ConsoleMods Wiki — PS4" to "https://consolemods.org/wiki/Main_Page"), related = listOf("retro.ps4-firmware-compatibility", "shopping.storage-basics")),
        guide("retro.ps5-current-research", "Retro & Android", "PS5 homebrew research: treat compatibility as a moving snapshot", "PS5 research changes quickly and varies by exact firmware, hardware and exploit chain. This article intentionally avoids a static support promise.",
            block("Check the actual state", "Record the full system software version and hardware model from the console's information screen.", "Separate a published vulnerability, a proof of concept, an entry point and a usable homebrew environment; they are not the same milestone.", "Read the project README, supported-version list, open issues and latest release date before changing the console.", "Do not update a console you want to research until you understand whether the update is reversible; console firmware rollback is generally not a routine user option."),
            block("Research safely", "Prefer the project's own repository and maintainers' release notes, then use specialist wikis for context.", "Avoid binaries from comments, shortened links or video descriptions unless they are independently verified against the project source.", "Back up captures and saves with official methods, and do not expect online services to remain available after system changes.", "No PS5 firmware is marked supported in this offline guide; verify current project documentation before acting."),
            sources = listOf("ConsoleMods Wiki" to consoleMods, "PS5 homebrew project example — check its live README and support list" to "https://github.com/ps5-hen/ps5-hen", "PlayStation 5 support" to "https://www.playstation.com/en-ie/support/hardware/ps5/"), related = listOf("retro.homebrew-source-checking", "retro.ps4-firmware-compatibility")),
        guide("retro.homebrew-source-checking", "Retro & Android", "Verify console homebrew sources before downloading", "A trustworthy guide names its maintainer, supported models and firmware, required files, checksums where provided and recovery limitations.",
            block("Source hierarchy", "Start with the official project repository or publisher's documentation and its linked releases.", "Use ConsoleMods and console-specific technical wikis for model context; they are community references, not Sony documentation.", "A tutorial video can explain a process, but verify its date, exact console model and firmware against current written documentation.", "Community posts and Reddit can help diagnose a symptom; confirm any firmware claim with the project or maintained compatibility reference."),
            block("Download hygiene", "Check repository owner, release tags, source files, signatures or published hashes where available.", "Do not run an unknown host utility or install an unknown package merely because a guide recommends it.", "Never download commercial game or BIOS files from unofficial sources; use software and dumps you are legally entitled to use.", "Keep a record of source URL, date checked, release version and device/firmware that the instructions claim to support."),
            sources = listOf("ConsoleMods Wiki — community reference" to consoleMods, "PS2 Homebrew Projects" to "https://github.com/ps2homebrew", "MODDED WARFARE — video education" to "https://www.youtube.com/@moddedwarfare"), related = listOf("retro.ps2-homebrew-overview", "retro.ps3-models-cfw-hen", "retro.ps4-firmware-compatibility", "retro.ps5-current-research")),
        guide("retro.android-device-basics", "Retro & Android", "Android versions, model numbers and update support", "An Android version number alone does not tell you whether a specific device is supported or secure.",
            block("Identify the software", "Record manufacturer, exact model code, Android version, security patch date, build number and carrier/region variant.", "Check the manufacturer's update page for the exact model; update schedules differ across devices with the same marketing name.", "A newer Android release may not be available for older hardware, and custom ROM support depends on a maintained device-specific build."),
            block("Plan an update", "Back up irreplaceable data, confirm battery and storage, use a stable connection and install updates from Settings or the manufacturer's signed tool.", "After an update, check calls, mobile data, Wi-Fi, Bluetooth, camera, banking apps and accessibility features.", "If updates have ended, review the device's threat model and avoid sensitive use if security fixes are no longer available.", "AOSP describes the platform; it does not mean every Android device receives identical Google apps, drivers or support."),
            sources = listOf("Android Open Source Project — overview" to "https://source.android.com/docs/setup/about", "Android security bulletins" to "https://source.android.com/docs/security/bulletin"), related = listOf("retro.android-bootloader-and-partitions", "shopping.android-device-choice")),
        guide("retro.android-bootloader-and-partitions", "Retro & Android", "Bootloaders, partitions and Verified Boot", "The boot chain checks software integrity. Unlocking a bootloader changes the device's security state and usually erases user data.",
            block("Plain-language model", "Boot ROM starts the bootloader; the bootloader verifies later boot images and loads the operating system.", "Partitions are named storage regions such as boot, vendor, system and userdata; layout and flashing rules vary by device and Android generation.", "Android Verified Boot checks authenticity and integrity, while rollback protection can reject older vulnerable software.", "A/B update slots and dynamic partitions mean a generic flashing command may target the wrong image or partition."),
            block("Before any unlock or flash", "Read the exact manufacturer's instructions and confirm that the exact model permits bootloader unlocking.", "Assume unlocking wipes data. Create and verify a backup first; cloud sync may not include all local app data.", "Understand relocking requirements and risks. Relocking with a mismatched or modified image can prevent boot.", "Use current platform-tools and the device-specific guide. Do not copy a command from another phone because the connector looks similar."),
            sources = listOf("AOSP — lock and unlock the bootloader" to androidBootloader, "AOSP — Verified Boot" to "https://source.android.com/docs/security/features/verifiedboot", "Android platform-tools" to "https://developer.android.com/tools/releases/platform-tools"), related = listOf("retro.android-rooting", "retro.android-recovery")),
        guide("retro.android-rooting", "Retro & Android", "Rooting with Magisk: purpose, risks and preparation", "Root access changes the security boundary of Android. Magisk is a maintained open-source project, but compatibility is device and build specific.",
            block("What root changes", "Root gives selected processes elevated privileges that can read or change protected system data.", "Magisk uses a systemless approach on supported setups and includes root management and boot-image tooling; its current documentation defines supported installation paths.", "Root can break app integrity checks, contactless payments, work profiles, banking apps and over-the-air updates.", "An unlocked bootloader and modified boot image can weaken Verified Boot assurances and expose data if the device is lost."),
            block("Prepare safely", "Confirm the exact model, firmware build and official installation guide; do not use a patched image from a different build.", "Back up all data and retain the matching stock boot image or factory package from the manufacturer.", "Read the project's release notes and recovery instructions before installing modules; a bad module can cause boot loops.", "Do not grant root to an app unless you trust its author and understand what data and commands it can access."),
            sources = listOf("Magisk official documentation" to "https://topjohnwu.github.io/Magisk/", "Magisk official project" to "https://github.com/topjohnwu/Magisk", "AOSP — Verified Boot" to "https://source.android.com/docs/security/features/verifiedboot"), related = listOf("retro.android-bootloader-and-partitions", "retro.android-recovery")),
        guide("retro.android-recovery", "Retro & Android", "Android backup and recovery checklist", "Make recovery plans before a fault or modification. A backup is useful only if you know what it contains and can restore it.",
            block("Back up", "Check Google or manufacturer sync status for contacts, photos and settings; sync is not necessarily a full device image.", "Export important authenticator recovery codes, local documents and app-specific data to a separate secure location.", "Copy photos and files to a computer or external drive and open a few copied files to confirm the backup works.", "Record the exact model, build number and official factory-image or recovery instructions."),
            block("If the phone will not start", "Charge with a known-good cable and adapter; remove accessories and record the screen, vibration and LED behaviour.", "Use the model-specific recovery menu and official manufacturer instructions; understand which options erase data.", "Do not factory-reset before checking whether local-only files are recoverable.", "If the device is encrypted and storage hardware has failed, recovery may be impossible; consult a repair specialist before repeated experiments."),
            sources = listOf("Google Pixel repair and software support" to "https://support.google.com/pixelphone/", "Android backup help" to "https://support.google.com/android/answer/2819582"), related = listOf("retro.android-bootloader-and-partitions", "retro.android-device-basics")),
        guide("retro.android-app-sources-and-tv", "Retro & Android", "Android app sources, Android TV and Google TV", "Install apps from sources you trust and verify device compatibility; alternative repositories do not guarantee that every app is safe or supported.",
            block("App sources", "Google Play is the default managed source for many devices. F-Droid is a repository and client focused on free and open-source Android software.", "For any APK, check the publisher, package name, requested permissions, signature and update source. A familiar icon is not proof of authenticity.", "Avoid APK sites that repackage apps, hide provenance or ask you to disable protections without a clear reason.", "Do not install apps from random QR codes, file hosts or social-media comments."),
            block("Android TV troubleshooting", "Check free internal storage, app cache, system update, network connectivity and the app's own service status.", "Restart the device and app, then clear only the app cache before considering clearing storage or reinstalling; clearing data can remove sign-ins and downloads.", "On Android TV/Google TV, confirm an app supports the TV interface and the installed OS version; mobile app availability does not guarantee TV support.", "For app install or playback errors, record device model, Android TV version, app version and exact error before seeking support."),
            sources = listOf("F-Droid official repository" to "https://f-droid.org/en/", "F-Droid security model" to "https://f-droid.org/docs/Security_Model/", "Android TV help" to "https://support.google.com/androidtv/"), related = listOf("retro.android-device-basics", "retro.android-recovery")),
        guide("retro.android-resource-directory", "Retro & Android", "Curated Android and console reference directory", "These entry points are starting places, not guarantees that every guide remains current. Check the date, exact model and release notes before following technical instructions.",
            block("Console projects and communities", "ConsoleMods Wiki: community-maintained model guides and technical background for PlayStation systems. Verify compatibility against the linked project documentation.", "PS2 Homebrew Projects: repositories for projects such as Open PS2 Loader; inspect the release page and user guide for current setup and compatibility.", "PS3HEN: official project repository and release information. Confirm exact supported hardware and firmware before proceeding.", "MODDED WARFARE: video tutorials and demonstrations. Pair each video with a current written compatibility reference; video upload date matters."),
            block("Android projects and primary references", "AOSP: platform source and architecture/security documentation; device manufacturers add their own drivers and support.", "LineageOS device wiki: installation steps are device-specific; use only the page for the exact model and read every warning before starting.", "Magisk: official documentation and GitHub releases; avoid unofficial mirrors.", "F-Droid: official free/open-source app catalogue; understand its repository and signature model."),
            block("Last-reviewed policy", "Direct links and project identities were checked on 18 October 2026; this is not a live compatibility check.", "No static PS4 or PS5 firmware table is embedded. Use maintained compatibility charts and exact project release notes on the day of use.", "Community wikis and forums can contain useful experience but are not manufacturer specifications or authoritative firmware support."),
            sources = listOf("ConsoleMods Wiki" to consoleMods, "PS2 Homebrew Projects" to "https://github.com/ps2homebrew", "PS3HEN" to "https://github.com/PS3Xploit/PS3HEN", "MODDED WARFARE" to "https://www.youtube.com/@moddedwarfare", "AOSP" to "https://source.android.com/", "LineageOS device list" to "https://wiki.lineageos.org/devices/", "Magisk" to "https://github.com/topjohnwu/Magisk", "F-Droid" to "https://f-droid.org/en/"), related = listOf("retro.homebrew-source-checking", "retro.android-device-basics")),

        // Shopping references used by other areas.
        guide("shopping.storage-basics", "Shopping", "Choose storage for projects and backups", "Capacity, interface, sustained workload, enclosure cooling and backup discipline matter more than a single advertised speed.",
            block("Match the medium", "HDDs offer low cost per terabyte for bulk storage but have moving parts; SSDs are faster and more shock-resistant in ordinary use but still fail.", "Check connector and protocol: USB-C describes a connector shape, not a guaranteed transfer rate or feature set.", "For a console or device, consult its official or maintained compatibility guidance before buying an internal drive or expansion card."),
            block("Protect the data", "Keep another copy on a separate device or service; two partitions on one physical drive are not two backups.", "Use a clear folder scheme and periodically open sample files from the backup.", "For long-term storage, label the device, date and contents, and refresh the copy before relying on aging media.", "Avoid storing the only copy of family photos or console saves on a single external drive."),
            related = listOf("shopping.specifications-that-matter", "retro.ps2-models-storage", "retro.ps4-backup-and-recovery"))
    )
}
